import { Session } from 'node:inspector/promises'
import { readFile, writeFile } from 'node:fs/promises'
import { PNG } from 'pngjs'
import { encodeTransplant } from '../../../benchmark/jpegxl/lossy-lab/transplant.ts'
import { libjxlPortOverrides } from '../../../benchmark/jpegxl/lossy-lab/libjxl-ports.ts'
import { libjxlStandaloneOverrides } from './base/libjxl-standalone-port.ts'
import { hash } from '../../../benchmark/jpegxl/comparison/io.ts'
const [id, mode] = process.argv.slice(2)
if (!id || (mode !== 'control' && mode !== 'candidate')) throw new Error('Supply development id and mode')
const root = '.tmp/jpegxl-lossy-lab/selector-bound-20261029'
const input = PNG.sync.read(await readFile(`.tmp/jpegxl-lossy-lab/corpus-512-v2/${id}.png`))
const pixels = Uint8Array.from(input.data)
const encode = () => encodeTransplant(pixels, input.width, input.height, 2,
  mode === 'control' ? libjxlPortOverrides('standalone-forward-all', 2, input.width, input.height)
    : libjxlStandaloneOverrides(2, input.width, input.height, 'standalone-regularized-half'))
for (let i = 0; i < 2; i++) await encode()
const profiler = new Session()
profiler.connect()
await profiler.post('Profiler.enable')
await profiler.post('Profiler.start')
const results = []
for (let i = 0; i < 3; i++) {
  const result = await encode()
  results.push({ hash: hash(result.bytes), bytes: result.bytes.length, managedPeakBytes: result.managedPeakBytes })
}
const { profile } = await profiler.post('Profiler.stop')
profiler.disconnect()
await writeFile(`${root}/${id}-${mode}.cpuprofile`, JSON.stringify(profile))
await writeFile(`${root}/${id}-${mode}-profile-receipt.json`, JSON.stringify(results, null, 2))

import { readFile, writeFile } from 'node:fs/promises'
import { PNG } from 'pngjs'
import { encodeTransplant } from '../../../benchmark/jpegxl/lossy-lab/transplant.ts'
import { libjxlPortOverrides } from '../../../benchmark/jpegxl/lossy-lab/libjxl-ports.ts'
import { libjxlStandaloneOverrides as baseOverrides } from './base/libjxl-standalone-port.ts'
import { libjxlStandaloneOverrides as optimized } from './trial1/libjxl-standalone-port.ts'
import type { JpegXlDevelopmentDecisions } from '../../../src/codecs/jpegxl-development-decisions.ts'
import { hash } from '../../../benchmark/jpegxl/comparison/io.ts'
const [id, trialName, countText = '15'] = process.argv.slice(2)
if (!id || !trialName || !/^trial[1-3]$/.test(trialName)) throw new Error('Need image and trial')
const count = Number(countText)
if (!Number.isSafeInteger(count) || count < 7 || count > 31) throw new Error('Invalid count')
const root = '.tmp/jpegxl-lossy-lab/selector-bound-20261029'
const input = PNG.sync.read(await readFile(`.tmp/jpegxl-lossy-lab/corpus-512-v2/${id}.png`))
const pixels = Uint8Array.from(input.data)
const rows = []
const names = ['control', 'base', 'optimized'] as const
for (let trial = -2; trial < count; trial++) {
  const offset = ((trial % 3) + 3) % 3
  for (let n = 0; n < 3; n++) {
    const mode = names[(offset + n) % 3]
    const decisions: JpegXlDevelopmentDecisions = mode === 'control'
      ? libjxlPortOverrides('standalone-forward-all', 2, input.width, input.height)
      : mode === 'base' ? baseOverrides(2, input.width, input.height, 'standalone-regularized-half')
      : optimized(2, input.width, input.height, 'standalone-regularized-half')
    const start = performance.now()
    const result = await encodeTransplant(pixels, input.width, input.height, 2, decisions)
    const row = { trial, mode, milliseconds: performance.now() - start, hash: hash(result.bytes), bytes: result.bytes.length, managedPeakBytes: result.managedPeakBytes }
    rows.push(row)
    console.log(JSON.stringify(row))
  }
  const pair = rows.filter(row => row.trial === trial && row.mode !== 'control')
  if (pair[0]?.hash !== pair[1]?.hash || pair[0]?.managedPeakBytes !== pair[1]?.managedPeakBytes) throw new Error('Frozen candidate changed')
}
await writeFile(`${root}/${trialName}-${id}-time.json`, JSON.stringify({ id, distance: 2, count, rows }, null, 2))

