import { readFile, writeFile } from 'node:fs/promises'
import { object, number } from '../../../benchmark/jpegxl/comparison/model.ts'
const input = process.argv[2]
if (!input) throw new Error('Need time JSON')
const data = object(JSON.parse(await readFile(input, 'utf8')))
if (!Array.isArray(data.rows)) throw new Error('Missing timing rows')
const rows = data.rows.map(object).filter(row => number(row.trial) >= 0)
const median = (values: number[]): number => {
  const sorted = [...values].sort((a, b) => a - b)
  const at = Math.floor(sorted.length / 2)
  const upper = sorted[at], lower = sorted[at - 1]
  if (upper === undefined) throw new Error('No samples')
  return sorted.length % 2 === 0 && lower !== undefined ? (lower + upper) / 2 : upper
}
const summaries = []
for (const reference of ['base', 'control']) {
  const pairs = []
  for (let i = 0; i < number(data.count); i++) {
    const a = rows.find(row => row.trial === i && row.mode === reference)
    const b = rows.find(row => row.trial === i && row.mode === 'optimized')
    if (!a || !b) throw new Error('Missing paired sample')
    pairs.push({ base: number(a.milliseconds), candidate: number(b.milliseconds),
      ratio: number(b.milliseconds) / number(a.milliseconds), equalBytes: a.hash === b.hash,
      equalManaged: a.managedPeakBytes === b.managedPeakBytes })
  }
  const m = median(pairs.map(p => p.ratio))
  summaries.push({ reference, count: pairs.length, medianRatio: m,
    mad: median(pairs.map(p => Math.abs(p.ratio - m))), faster: pairs.filter(p => p.ratio < 1).length,
    baseMedianMs: median(pairs.map(p => p.base)), candidateMedianMs: median(pairs.map(p => p.candidate)),
    allBytesEqual: pairs.every(p => p.equalBytes), allManagedEqual: pairs.every(p => p.equalManaged) })
}
await writeFile(input.replace(/\.json$/, '-summary.json'), JSON.stringify({ input, summaries }, null, 2))
console.log(JSON.stringify(summaries))

import { writeFile } from 'node:fs/promises'
import { inverseWeightedSelectorTransform } from '../../../benchmark/jpegxl/lossy-lab/selector-inverse-weights.ts'
import { jpegXlVarDctStrategyBlockWidths, jpegXlVarDctStrategyBlockHeights } from '../../../src/codecs/jpegxl-vardct-jpeg.ts'
import { selectorMaskLoss } from '../../../benchmark/jpegxl/lossy-lab/selector-mask-loss.ts'
import { inverseSelectorWithLossBound } from './trial3/selector-inverse-bound.ts'
const rows = []
for (const strategy of [4, 5, 6, 7, 10, 11, 18, 19, 20]) {
  const width = (jpegXlVarDctStrategyBlockWidths[strategy] ?? 0) * 8
  const height = (jpegXlVarDctStrategyBlockHeights[strategy] ?? 0) * 8
  const size = width * height
  for (const scale of [0, 0.0001, 1, 1000]) {
    const coefficients = Float64Array.from({length: size}, (_, i) => Math.sin(i * 7.13) * scale)
    const expected = new Float32Array(size), actual = new Float32Array(size), scratch = new Float64Array(size)
    const active = new Uint16Array(64)
    const mask = Float32Array.from({length: 4096}, (_, i) => 0.2 + ((i * 13) % 17) / 8)
    inverseWeightedSelectorTransform(strategy, coefficients, scratch, expected, active)
    const loss = selectorMaskLoss(expected, mask, width, height, 0, 0, 1)
    for (const limit of [Infinity, loss, loss / 100]) {
      actual.fill(NaN)
      const partial = inverseSelectorWithLossBound(strategy, coefficients, scratch, actual, active, mask, 0, 0, 1, limit)
      if (partial === undefined) {
        if (!actual.every((v, i) => Object.is(v, expected[i]))) throw new Error('Exact inverse mismatch')
      } else if (!(partial <= loss && partial > limit)) throw new Error('Invalid subset lower bound')
      rows.push({strategy, scale, limit: Number.isFinite(limit) ? limit : 'Infinity', loss, partial: partial ?? null})
    }
  }
}
await writeFile('.tmp/jpegxl-lossy-lab/selector-bound-20261029/inverse-check.json', JSON.stringify(rows, null, 2))
console.log(JSON.stringify({cases: rows.length}))

import { cp, mkdtemp, readFile, readdir, writeFile } from 'node:fs/promises'
import { spawnSync } from 'node:child_process'
import { createHash } from 'node:crypto'
const root = '.tmp/jpegxl-lossy-lab/selector-bound-20261029'
const destination = 'benchmark/jpegxl/lossy-lab'
const prefix = 'benchmark/jpegxl/lossy-lab/'
const normalize = (text: string): string => text.replaceAll('../../../../benchmark/jpegxl/lossy-lab/', './').replaceAll('../../../../src/', '../../../src/')
const command = (args: string[]): string => {
  const result = spawnSync('git', args, {encoding: 'utf8'})
  if (result.status !== 0) throw new Error(`${args.join(' ')}: ${result.stderr}`)
  return result.stdout
}
const reproduce = await mkdtemp(`${root}/reproduce-`)
await cp('.tmp/jpegxl-lossy-lab/detail-guard-20261029/archive-base', reproduce, {recursive: true})
command(['apply', `--directory=${reproduce}`, `${destination}/DETAIL-GUARD-EXPERIMENT.patch`])
const sourceRecords = []
const reconstructedTrials = []
for (const name of await readdir(`${root}/base`)) {
  const source = normalize(await readFile(`${root}/base/${name}`, 'utf8'))
  const rebuilt = await readFile(`${reproduce}/${prefix}${name}`, 'utf8')
  if (source !== rebuilt) throw new Error(`Archived quality base differs: ${name}`)
  sourceRecords.push({name, sha256: createHash('sha256').update(source).digest('hex')})
}
for (const trial of ['trial1', 'trial2', 'trial3']) {
  let patch = ''
  for (const name of await readdir(`${root}/${trial}`)) {
    const changed = normalize(await readFile(`${root}/${trial}/${name}`, 'utf8'))
    const exists = (await readdir(`${root}/base`)).includes(name)
    const base = exists ? normalize(await readFile(`${root}/base/${name}`, 'utf8')) : ''
    if (base === changed) continue
    await writeFile(`${root}/diff-before`, base)
    await writeFile(`${root}/diff-after`, changed)
    const result = spawnSync('diff', ['-u', '--label', exists ? `a/${prefix}${name}` : '/dev/null', '--label', `b/${prefix}${name}`, `${root}/diff-before`, `${root}/diff-after`], {encoding:'utf8'})
    if (result.status !== 1) throw new Error(`Unexpected diff status ${result.status}`)
    patch += `diff --git a/${prefix}${name} b/${prefix}${name}\n${exists ? '' : 'new file mode 100644\n'}${result.stdout}`
  }
  const patchPath = `${destination}/SELECTOR-BOUND-${trial.toUpperCase()}.patch`
  await writeFile(patchPath, patch)
  command(['apply', '--check', `--directory=${reproduce}`, patchPath])
  const trialRoot = await mkdtemp(`${root}/reconstruct-${trial}-`)
  await cp(reproduce, trialRoot, {recursive:true})
  command(['apply', `--directory=${trialRoot}`, patchPath])
  const hashes = []
  for (const name of await readdir(`${root}/${trial}`)) {
    const expected = normalize(await readFile(`${root}/${trial}/${name}`, 'utf8'))
    const rebuilt = await readFile(`${trialRoot}/${prefix}${name}`, 'utf8')
    if (expected !== rebuilt) throw new Error(`Reconstructed trial differs: ${trial}/${name}`)
    hashes.push({name,sha256:createHash('sha256').update(rebuilt).digest('hex')})
  }
  reconstructedTrials.push({trial,hashes})
}
await writeFile(`${root}/archive-verification.json`, JSON.stringify({qualityBase:'97c76933a1cfa7f4df4ffdb92349172d1f53c7ca', qualityPatch:'DETAIL-GUARD-EXPERIMENT.patch', speedBase:'2c320e3bbecd81f1343a487d601366808eeb6b50', normalizedSourceHashes:sourceRecords, reconstructedTrials, patchChecks:['trial1','trial2','trial3'], status:'passed'}, null, 2))
console.log('All three patches apply to the reconstructed frozen quality base')

/**
 * Source: libjxl tools/ssimulacra2.cc, SSIMMap, v0.12.0,
 * a7a9c787341cf703dede03c2009fa460cae5e5df.
 * Copyright (c) the JPEG XL Project Authors. BSD-3-Clause
 * Changes: the regularized mode reuses the structure denominator and 0.0009
 * stabilizer. First-party 8x8 box moments on preconditioned luma replace Gaussian
 * display moments; DC, other channels, scales and edge terms are excluded.
 * Contrast-only and unregularized modes are first-party diagnostic alternatives.
 * No peer decisions. This is not a metric implementation or public encoder.
 */
export function selectorDetailLoss(
  source: Float32Array,
  error: Float32Array,
  width: number,
  height: number,
  scale: number,
  kind: 'contrast' | 'structure' | 'regularized' | 'lost-detail',
): number {
  let total = 0
  for (let by = 0; by < height; by += 8)
    for (let bx = 0; bx < width; bx += 8) {
      let sum = 0,
        sumError = 0,
        square = 0,
        squareError = 0,
        cross = 0
      for (let y = 0; y < 8; y++)
        for (let x = 0; x < 8; x++) {
          const at = (by + y) * width + bx + x
          const value = source[at] ?? 0
          const residual = (error[at] ?? 0) * scale
          sum += value
          sumError += residual
          square += value * value
          squareError += residual * residual
          cross += value * residual
        }
      const variance = Math.max(0, square - (sum * sum) / 64)
      const errorVariance = Math.max(0, squareError - (sumError * sumError) / 64)
      const covariance = cross - (sum * sumError) / 64
      const reconstructed = Math.max(0, variance + errorVariance - 2 * covariance)
      if (kind === 'lost-detail') {
        // First-party asymmetric residual: only locally removed detail matters.
        // Normalize by error energy so flat offsets and added contrast contribute zero.
        let lostEnergy = 0
        for (let y = 0; y < 8; y++)
          for (let x = 0; x < 8; x++) {
            const at = (by + y) * width + bx + x
            const centered = (source[at] ?? 0) - sum / 64
            const residual = (error[at] ?? 0) * scale - sumError / 64
            const lost = Math.max(0, Math.abs(centered) - Math.abs(centered - residual))
            lostEnergy += lost * lost
          }
        total += Math.sqrt(Math.min(1, lostEnergy / Math.max(errorVariance, 64e-8)))
        continue
      }
      // Stabilize flat cells in the physical XYB scale; DC offsets are excluded.
      const epsilon = kind === 'regularized' ? 64 * 0.0009 : 64e-8
      total +=
        kind === 'contrast'
          ? Math.max(0, 1 - Math.sqrt((reconstructed + epsilon) / (variance + epsilon)))
          : Math.min(1, errorVariance / (variance + reconstructed + epsilon))
    }
  return total / ((width * height) / 64)
}

/**
 * Sources: libjxl-tiny encoder/enc_ac_strategy.cc at
 * 8eae18172059d54f5c734ca814f23b96eebff859; libjxl lib/jxl/enc_ac_strategy.cc
 * at v0.12.0, a7a9c787341cf703dede03c2009fa460cae5e5df.
 * Copyright (c) the JPEG XL Project Authors. BSD-3-Clause
 * Changes: scalar TypeScript cost models and hierarchical selection, using our
 * transforms, quantization fields, CfL and writer. Tiny's adaptive mask is held
 * at one; v0.12's pixel mask can be held at one or ported separately. Maximum-footprint Q is
 * used instead of v0.12's sixteenth norm except in spatial-source mode, which
 * uses the separately ported norm and post-selection field adjustment.
 * That mode scores unscaled normative matrices as the native heuristic does;
 * the writer still applies the signaled chroma matrix scales.
 * Optional error guard is our own.
 * Bounded caching, admissible cost pruning, Y-first evaluation, tile traversal
 * and the compact candidate menu are first-party speed adaptations.
 * Writer-estimate experiments independently match the final quantization field,
 * chroma matrix scales and rate-aware rounding used by our writer.
 * Tiny's split-cost literal is written as its representable JavaScript double.
 * First-party pruning includes known luma cost, minimum remaining channel
 * entropy and the remaining budget for rectangle partitions.
 * This is a development experiment, never imported by the public encoder.
 */
import { selectorTileMask } from '../../../../benchmark/jpegxl/lossy-lab/selector-tile-mask.ts'
