  if (
    value === 'tiny' ||
    value === 'spatial' ||
    value === 'spatial-masked' ||
    value === 'spatial-guarded' ||
    value === 'spatial-actual' ||
    value === 'spatial-actual-guarded' ||
    value === 'spatial-source'
